#include <iostream>
int main() {
    int c = 0;
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 4; j++)
            c++;
    std::cout << c << "\n";
    return 0;
}

#include <iostream>
int main() {
    int n = 40, steps = 0;
    while (n > 1) {
        n = n / 2;
        steps++;
    }
    std::cout << steps << "\n";
    return 0;
}

#include <iostream>
int main() {
    int n = 4, s = 0;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= i; j++)
            s++;
    std::cout << s << "\n";
    return 0;
}

#include <iostream>
int main() {
    int n = 100, c = 0;
    for (int i = 0; i < n; i++) c++;
    for (int j = 0; j < n; j++) c++;
    std::cout << c << "\n";
    return 0;
}

#include <iostream>
#include <vector>
int main() {
    int n = 5;
    std::vector<int> v;
    for (int i = 0; i < n; i++) v.push_back(i * i);
    int total = 0;
    for (int x : v) total += x;
    std::cout << v.size() << " " << total << "\n";
    return 0;
}
